function smart_sort_array($set, $order) {
    // Sort the set based on the 'age' field in descending order if order is 1,
    // otherwise sort in ascending order.
    usort($set, function ($a, $b) use ($order) {
        return strcmp((string)$a['age'], (string)$b['age']);
    });

    // If order is 0, reverse the sorted array.
    if ($order == 0) {
        $set = array_reverse($set);
    }

    return $set;
}

