import { Controller, Get, UseGuards, Request, Response } from '@nestjs/common';
import { AuthGuard } from './auth.guard';
import { UserService } from './user.service';
import { PermissionsService } from './permissions.service';

@Controller('auth')
export class AuthController {
  constructor(
    private userService: UserService,
    private permissionsService: PermissionsService,
  ) {}

  @Get()
  async getPermissions(@Request() req) {
    const user = await this.userService.getUserByToken(req.headers['authorization']);
    if (!user) return null;

    const permissions = await this.permissionsService.getPermissions(user.role);
    return permissions;
  }
}

// auth.guard.ts

import { Injectable, CanActivate, ExecutionContext } from '@nestjs/common';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';

@Injectable()
export class AuthGuard implements CanActivate {
  constructor(private authService: AuthService) {}

  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest();

    const token = request.headers.authorization.split(' ')[1];
    if (token && !this.authService.validateToken(token)) {
      return false;
    }

    return true;
  }
}

// user.service.ts

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
